# 带 tenant_id 的业务表启用并强制 RLS；未设置 app.tenant_id 时失败关闭。
# tenants/users/auth_sessions 不在此列：登录核验发生在租户上下文建立之前，
# 由窄权限认证查询访问。
_TENANT_TABLES = (
    "cases",
    "case_access_grants",
    "stored_objects",
    "source_documents",
    "document_versions",
    "upload_sessions",
    "upload_files",
    "upload_events",
    "idempotency_records",
    "audit_events",
)

_AUTH_TABLES = ("tenants", "users", "auth_sessions")


def _apply_rls() -> None:
    for table in _TENANT_TABLES:
        op.execute(f"ALTER TABLE {table} ENABLE ROW LEVEL SECURITY")
        # FORCE 让表 owner 也受策略约束，避免用迁移角色连接时意外绕过
        op.execute(f"ALTER TABLE {table} FORCE ROW LEVEL SECURITY")
        op.execute(
            f"""
            CREATE POLICY {table}_tenant_isolation ON {table}
            USING (tenant_id = nullif(current_setting('app.tenant_id', true), '')::uuid)
            WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id', true), '')::uuid)
            """
        )
        # 运行时角色只有 DML，没有 DDL 与 BYPASSRLS
        op.execute(f"GRANT SELECT, INSERT, UPDATE, DELETE ON {table} TO logistics_app, logistics_worker")

    # 认证表只给最小权限：读用户与会话、写会话
    op.execute("GRANT SELECT ON tenants, users TO logistics_app")
    op.execute("GRANT SELECT, INSERT, UPDATE ON auth_sessions TO logistics_app")


def _drop_rls() -> None:
    for table in _TENANT_TABLES:
        op.execute(f"DROP POLICY IF EXISTS {table}_tenant_isolation ON {table}")
        op.execute(f"ALTER TABLE {table} NO FORCE ROW LEVEL SECURITY")
        op.execute(f"ALTER TABLE {table} DISABLE ROW LEVEL SECURITY")
